window.HB_TRIP_HELPERS.getDayHighlights = function(city, areas) {
      const map = {
        Paris: [
          `First walk through ${areas[0]}`,
          `Cafe time and wandering in ${areas[1]}`,
          "Eiffel Tower",
          "Signature dinner reservation",
          `Final pastry stop in ${areas[1]}`
        ],
        Lisbon: [
          `First walk through ${areas[0]}`,
          `Cafe stop and views in ${areas[1]}`,
          "Alfama lookout and old-town views",
          "Signature seafood dinner",
          `Final market stop in ${areas[0]}`
        ],
        Rome: [
          `First stroll through ${areas[0]}`,
          `Lunch and wandering in ${areas[1]}`,
          "Colosseum or major landmark visit",
          "Signature Roman dinner",
          `Final piazza stop in ${areas[2]}`
        ],
        Tokyo: [
          `First walk through ${areas[0]}`,
          `Neighborhood food stop in ${areas[2]}`,
          "Main city highlight",
          "Signature dinner experience",
          `Final slow morning in ${areas[1]}`
        ],
        Bermuda: [
          "Hamilton waterfront + easy first dinner",
          "South Shore beach time",
          "Horseshoe Bay + family snorkeling",
          "St. George's and a seafood dinner",
          "Slow final morning near the water"
        ],
        London: [
          "Covent Garden + Seven Dials",
          "Big Ben + Buckingham Palace",
          "South Bank + Sky Garden",
          "Portobello Road + Notting Hill dinner",
          "Kensington museums + garden close"
        ]
      };
      const guideDetail = getGuideDetailForTripCity(city);
      if (guideDetail) {
        const concreteHighlights = uniqueList(
          guideDetail.bestFirstTimers,
          guideDetail.bestAttractions,
          guideDetail.bestDinner,
          guideDetail.bestUnique,
          guideDetail.bestCouples
        ).slice(0, 5);

        if (concreteHighlights.length >= 5) {
          return concreteHighlights;
        }
      }

      return map[city] || [
        `First walk through ${areas[0]}`,
        `Neighborhood highlight in ${areas[1]}`,
        "Main city sight",
        "Signature experience",
        `Easy final stop in ${areas[1]}`
      ];
    }


